(()=>{
const main=document.querySelector('main');const specs=[['overview','總覽','target'],['dashboard','戰情中心','chart'],['solutions','解決方案','flow'],['investment','投資與新事業','target'],['results','專案實績','signal'],['contact','需求洽談','people']];
const panes={};specs.forEach(([id,label])=>{const p=document.createElement('div');p.className='workspace-pane';p.id='view-'+id;p.setAttribute('aria-label',label);panes[id]=p;main.appendChild(p)});
function move(selector,id){const el=document.querySelector(selector);if(el)panes[id].appendChild(el)}
move('.hero','overview');move('#command-dashboard','dashboard');move('#solutions','solutions');move('#venture','investment');move('#threads-results','results');move('#brief','contact');
function fold(selector,id,label){const el=document.querySelector(selector);if(!el)return;const detail=document.createElement('details');detail.className='workspace-details wrap';detail.innerHTML=`<summary>${label}<span>＋</span></summary>`;detail.appendChild(el);panes[id].appendChild(detail)}
fold('#services','solutions','查看完整交付能力');fold('.sector-section','investment','跨境資產與不動產的應用情境');fold('#cases','results','系統建構與行銷分析專案');fold('#diagnosis','contact','不知道從哪裡開始？進行 5 題診斷');fold('#calculator','contact','試算流程改善的工時價值');fold('#blueprint','contact','查看合作流程');
// Remove the superseded presentation sections from the workstation.
document.querySelector('.brand-gallery')?.remove();document.querySelector('.proof')?.remove();
const heroCore=document.querySelector('.radar-center');if(heroCore)heroCore.innerHTML='<img src="assets/f-mark.svg" alt="FION FORWARD" width="55" height="55">';document.querySelector('.rail-brand')?.replaceChildren();const rb=document.querySelector('.rail-brand');if(rb)rb.innerHTML='<img src="assets/f-mark.svg" width="28" height="28" alt="FION FORWARD">';
const header=document.querySelector('header');header.innerHTML=`<div class="workspace-top wrap"><a href="#overview" class="workspace-brand"><img src="assets/f-mark.svg" width="43" height="43" alt="FION FORWARD"><span>FION FORWARD<small>STRATEGY & INTELLIGENCE</small></span></a><div class="workspace-position">企業主顧問 <span>/</span> AI 轉型 <span>/</span> 新事業落地</div><a class="workspace-start" href="#contact">討論企業需求 <svg class="icon" aria-hidden="true"><use href="#ic-people"/></svg></a></div><nav class="workspace-nav wrap" aria-label="工作台導覽">${specs.map(([id,name,icon])=>`<a href="#${id}" data-view="${id}"><svg class="icon" aria-hidden="true"><use href="#ic-${icon}"/></svg><span>${name}</span></a>`).join('')}</nav>`;
const overviewCards=document.createElement('div');overviewCards.className='overview-shortcuts wrap';overviewCards.innerHTML=`<a href="#dashboard"><span>01 / INTELLIGENCE</span><h3>看見經營瓶頸</h3><p>五大互動戰情介面</p><svg class="icon" aria-hidden="true"><use href="#ic-chart"/></svg></a><a href="#solutions"><span>02 / TRANSFORMATION</span><h3>讓策略走進流程</h3><p>品牌、網站、AI 與營運</p><svg class="icon" aria-hidden="true"><use href="#ic-flow"/></svg></a><a href="#investment"><span>03 / VENTURE</span><h3>投入前，先驗證</h3><p>研究、盡調與落地規劃</p><svg class="icon" aria-hidden="true"><use href="#ic-target"/></svg></a>`;panes.overview.appendChild(overviewCards);
const footer=document.querySelector('footer');const toggle=footer.querySelector('.motion-toggle');footer.innerHTML='<div class="workspace-status"><span>FION FORWARD <b>企業決策工作台</b></span><span>PRIVATE SHOWCASE / 示範數據已標示</span></div>';if(toggle)footer.firstChild.appendChild(toggle);
const aliases={'command-dashboard':'dashboard',venture:'investment',cases:'results','threads-results':'results',brief:'contact',diagnosis:'contact',calculator:'contact',blueprint:'contact',services:'solutions'};
let active='';function route(){let hash=decodeURIComponent(location.hash.slice(1)),id=aliases[hash]||hash;if(!panes[id])id='overview';Object.entries(panes).forEach(([k,p])=>p.hidden=k!==id);document.querySelectorAll('[data-view]').forEach(a=>{let on=a.dataset.view===id;a.classList.toggle('active',on);if(on)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});if(active!==id){window.scrollTo({top:0,behavior:'instant'});active=id}const target=document.getElementById(hash);if(target&&target!==panes[id]&&hash!==id){let d=target.closest('details');if(d)d.open=true}document.querySelectorAll('.reveal').forEach(el=>el.classList.add('visible'));document.title=specs.find(x=>x[0]===id)[1]+' · FION FORWARD';}
window.addEventListener('hashchange',route);route();
function syncMotion(){const off=document.body.classList.contains('motion-off')||matchMedia('(prefers-reduced-motion: reduce)').matches;document.querySelectorAll('svg').forEach(svg=>{if(typeof svg.pauseAnimations==='function'){if(off)svg.pauseAnimations();else svg.unpauseAnimations()}})}
document.addEventListener('click',e=>{if(e.target.closest('.motion-toggle,[data-intel]'))requestAnimationFrame(syncMotion)});syncMotion();
// Identity uses the vector mark only.
document.querySelectorAll('.hero .micro').forEach(el=>el.remove());
})();
